package com.smartcanteen.repo; import com.smartcanteen.domain.Order; import java.util.*; import org.springframework.data.jpa.repository.*; public interface OrderRepository extends JpaRepository<Order,Long>{List<Order> findByCustomerEmailOrderByCreatedAtDesc(String email); List<Order> findByStatusInOrderByCreatedAtAsc(Collection<Order.Status> statuses); @Query("select o.status, count(o) from Order o group by o.status") List<Object[]> countByStatus();}
